const ROOT = "/data/processed/phase3";
const PHASE4 = "/data/experiments/phase4";
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const CATS = ["Sports","Gaming","Education","Entertainment","Podcasts and Interviews","Instructional Content"];
const CAT_SHORT = {"Sports":"Sports","Gaming":"Gaming","Education":"Education","Entertainment":"Entertainment","Podcasts and Interviews":"Podcasts / Interviews","Instructional Content":"Instructional"};
const FUNCTIONS = ["excitement_appreciation","confusion","humor","instructional_reference","quality_complaint","navigation_indexing","other"];
const LABEL = {excitement_appreciation:"Excitement",confusion:"Confusion",humor:"Humor",instructional_reference:"Instructional",quality_complaint:"Quality complaint",navigation_indexing:"Navigation",other:"Other"};
const NAV = [
 ["Overview","◫","overview"],["Dataset","▤","dataset"],["Videos","▣","videos"],
 ["Behavioral Analysis","⌁","behavior","Current"],["Segment Explorer","▥","segments"],
 ["Candidate Moments","◎","candidates"],["Human Study","♙","human","Preview"],
 ["Project Progress","◷","progress"]
];
const STAGES = ["Dataset Construction","Automated Collection","Signal Preprocessing","Behavioral Salience","Network-Side QoE","Subjective QoE Study","Calibration & Augmentation","Evaluation","Adaptive Streaming Demo"];
let app = {videos:[],records:new Map(),features:[],featureMap:new Map(),candidates:[],predictions:[],model:null,status:null,page:"overview",videoId:null,bin:0,weights:[.25,.25,.25,.25],customWeights:false,sortKey:"title",sortDir:1,selected:new Set(JSON.parse(localStorage.getItem("qoe-selected")||"[]")),flags:JSON.parse(localStorage.getItem("qoe-flags")||"{}"),sidebar:false,participant:false,studyIndex:0};
const salienceCache=new Map();

async function json(path){const r=await fetch(path);if(!r.ok)throw Error(`${path}: ${r.status}`);return r.json();}
async function init(){
  try{
    const m=await json(`${ROOT}/manifest.json`);app.videos=m.videos.filter(v=>v.status==="processed");
    const [records,features,candidates,status,model,predictions]=await Promise.all([
      Promise.all(app.videos.map(v=>json(`${ROOT}/videos/${encodeURIComponent(v.videoId)}.json`))),
      json(`${PHASE4}/features.json`).catch(()=>({rows:[]})),json(`${PHASE4}/candidate-segments.json`).catch(()=>({segments:[]})),
      json(`${PHASE4}/status.json`).catch(()=>({status:"not_prepared"})),json(`${PHASE4}/model.json`).catch(()=>null),json(`${PHASE4}/predictions.json`).catch(()=>({predictions:[]}))
    ]);
    records.forEach(r=>app.records.set(r.videoId,r));app.features=features.rows||[];app.featureMap=new Map(app.features.map(f=>[`${f.videoId}:${f.binIndex}`,f.features]));app.candidates=candidates.segments||[];app.status=status;app.model=model;app.predictions=predictions.predictions||[];
    app.videoId=app.videos[0]?.videoId||null;app.weights=loadWeights();$("#topStatus").textContent=`${app.videos.length} videos · data ready`;
    renderNav();bindGlobal();navigate(location.hash.slice(1)||"overview",false);
  }catch(e){$("#pageContent").innerHTML=`<div class="card empty-state"><div class="empty-icon">⚠</div><b>Research dataset could not be loaded</b><p>${esc(e.message)}</p><p>Run the preprocessing commands, then serve the project folder over HTTP.</p></div>`;}
}
function renderNav(){
  const nav=$("#mainNav");nav.innerHTML=NAV.map(([name,icon,id,badge])=>`<button class="nav-item ${id===app.page?"active":""}" data-page="${id}" title="${name}"><span class="nav-icon">${icon}</span><span>${name}</span>${badge?`<i class="nav-badge">${badge}</i>`:""}</button>`).join("");
  $$(".nav-item",nav).forEach(b=>b.onclick=()=>navigate(b.dataset.page));
}
function bindGlobal(){
  $("#collapseSidebar").onclick=()=>{app.sidebar=!app.sidebar;document.body.classList.toggle("collapsed",app.sidebar)};
  $("#mobileMenu").onclick=()=>document.body.classList.toggle("mobile-open");
  document.addEventListener("click",e=>{if(e.target.closest(".mobile-menu"))return;if(document.body.classList.contains("mobile-open")&&!e.target.closest(".sidebar"))document.body.classList.remove("mobile-open")});
  window.addEventListener("hashchange",()=>navigate(location.hash.slice(1)||"overview",false));
}
function navigate(page,push=true){
  app.page=(page==="video"||NAV.some(x=>x[2]===page))?page:"overview";if(push)location.hash=app.page;
  $("#crumb").textContent=NAV.find(x=>x[2]===app.page)?.[0]||"Overview";renderNav();renderPage();document.body.classList.remove("mobile-open");window.scrollTo(0,0);
}
function titleBlock(kicker,title,sub,actions=""){return `<div class="page-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="header-actions">${actions}</div></div>`;}
function btn(text,action,kind=""){return `<button class="btn ${kind}" data-action="${action}">${text}</button>`;}
function exportRow(id){return `<div class="export-row"><button data-export="${id}:svg">SVG</button><button data-export="${id}:png">PNG</button><button data-export="${id}:csv">CSV</button></div>`;}
function cardTitle(title,sub="",action=""){return `<div class="panel-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:""}</div>${action?`<button class="panel-action" data-action="${action}">View all →</button>`:""}</div>`;}
function metric(label,value,foot,icon="◌",tone="") {return `<article class="card metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${icon}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${foot}</div></article>`;}
function renderPage(){const host=$("#pageContent");const pages={overview:overviewPage,dataset:datasetPage,videos:videosPage,video:videoPage,behavior:behaviorPage,segments:segmentsPage,candidates:candidatePage,experiments:experimentsPage,human:humanPage,models:modelsPage,results:resultsPage,collection:collectionPage,progress:progressPage,settings:settingsPage};host.innerHTML=(pages[app.page]||overviewPage)();bindPage();}
function recs(){return app.videos.map(v=>app.records.get(v.videoId)).filter(Boolean);}
function total(field){return recs().reduce((n,r)=>n+(Number(r[field])||0),0);}
function totalTimestamped(){return recs().reduce((n,r)=>n+(Number(r.sourceTimestampedCommentCount)||0),0);}
function categoryCounts(){return CATS.map(c=>({category:c,count:recs().filter(r=>r.category===c).length}));}
function phaseStatus(){return ["complete","complete","complete","current","upcoming","upcoming","upcoming","upcoming","conditional"];}
function pipeline(){return `<div class="card"><div class="pipeline">${STAGES.map((s,i)=>{const state=phaseStatus()[i];return `<div class="pipeline-step ${state}"><div class="pipeline-node">${state==="complete"?"✓":i+1}</div><div class="pipeline-name">${s}</div><div class="pipeline-meta">${state==="complete"?"Completed":state==="current"?"In progress":state==="conditional"?"Conditional":"Upcoming"}</div></div>`}).join("")}</div></div>`;}
function overviewPage(){
 const n=app.videos.length,categories=new Set(recs().map(r=>r.category)).size,bins=recs().reduce((x,r)=>x+r.bins.length,0),collected=total("collectedCommentCount"),ts=totalTimestamped();
 return `${titleBlock("RESEARCH WORKSPACE","Behavior-Aware QoE Research Dashboard","Understanding whether public viewer behavior can reveal segment-level QoE sensitivity.",btn("Export dataset","export-dataset","soft"))}
 <div class="grid cols-4" style="margin-bottom:15px">${metric("Videos",fmt(n),"balanced research sample","▣")}${metric("Content categories",fmt(categories),"four videos in each","◫")}${metric("Temporal segments",fmt(bins),"100 normalized moments per video","▥")}${metric("Public comments collected",fmt(collected),"top-level public comments","☷")}${metric("Timestamped comments",fmt(ts),"references linked to video moments","⌁")}${metric("Current research stage","4 / 9","behavioral salience modeling","◷","blue")}${metric("Dataset completion","100%","24 of 24 pilot videos processed","✓","green")}${metric("Pipeline status",app.model?"Model ready":"In progress",app.model?"initial model trained":"awaiting impairment measurements","◉","amber")}</div>
 <div style="margin-bottom:15px">${cardTitle("Research pipeline","From public signals to validated QoE estimates")} ${pipeline()}</div>
 <div class="grid cols-2" style="margin-bottom:15px"><section class="card card-pad">${cardTitle("Dataset distribution","Four videos per content category")}<div class="dist-list">${categoryCounts().map(x=>`<div class="dist-row"><span>${CAT_SHORT[x.category]}</span><div class="contribution-track"><i class="contribution-fill" style="width:${x.count/Math.max(1,n)*100}%"></i></div><b>${x.count}</b></div>`).join("")}</div></section><section class="card card-pad">${cardTitle("Behavioral signal overview","Signals summarized at segment level", "behavior")}${miniSignalBars()}</section></div>
 <div class="grid cols-2"><section class="card card-pad">${cardTitle("Recently analyzed videos","Open a video to inspect its signals", "videos")}${recentVideos()}</section><section class="card card-pad">${cardTitle("Research status","Completed work and what comes next", "progress")}${statusSummary()}</section></div>`;
}
function miniSignalBars(){const all=recs().flatMap(r=>r.bins.map((b,i)=>({r,b,i}))),absAvg=(key)=>avg(app.features.map(f=>Math.abs(f.features[key]||0))),means=[avg(all.map(x=>x.b.replayIntensity||0)),Math.min(1,absAvg("prominenceZ")/3),avg(all.map(x=>x.b.logNormalizedTimestampCount||0)),Math.min(1,(all.reduce((n,x)=>n+FUNCTIONS.reduce((s,k)=>s+(x.b.functionCounts[k]||0),0),0)/Math.max(1,all.length))/3),Math.min(1,(absAvg("replayZ")+absAvg("prominenceZ")+absAvg("commentActivityZ")+absAvg("emotionZ"))/12)],names=["Most Replayed activity","Replay prominence","Timestamp-comment activity","Comment function","Behavioral salience"],colors=["#3977d5","#739de0","#65a9a1","#8d9ed3","#315d99"];return `<div class="mini-bars">${names.map((x,i)=>`<div><span>${x}</span><i><b style="width:${Math.max(4,means[i]*100)}%;background:${colors[i]}"></b></i><small>${["R","P","C","E","B"][i]}</small></div>`).join("")}</div>`;}
function recentVideos(){return `<div class="recent-list">${recs().slice(0,4).map(r=>`<button class="recent-video" data-video="${r.videoId}"><img src="https://i.ytimg.com/vi/${r.videoId}/mqdefault.jpg" alt=""><span><b>${esc(r.title)}</b><small>${esc(CAT_SHORT[r.category]||r.category)} · ${duration(r.durationSeconds)}</small></span><i>→</i></button>`).join("")}</div>`;}
function statusSummary(){const done=app.status?.featureRows?"Behavioral features prepared for 2,400 moments.":"Signal processing complete for 24 videos.";return `<div class="summary-line"><span class="check-icon">✓</span><span><b>Public behavior signals processed</b><small>${done}</small></span><i class="pill green">COMPLETE</i></div><div class="summary-line"><span class="pending-icon">↗</span><span><b>Controlled impairment measurements</b><small>Awaiting source media and objective quality measurements.</small></span><i class="pill amber">NEXT</i></div><div class="summary-line"><span class="pending-icon">○</span><span><b>Subjective study and model validation</b><small>Planned after the controlled experiments.</small></span><i class="pill">UPCOMING</i></div>`;}

function datasetPage(){const acts=`${btn("Export CSV","export-dataset")}${btn("Refresh","refresh","soft")}`;return `${titleBlock("RESEARCH DATA","Dataset","24 videos across six categories · collected and preprocessed",acts)}<div class="card card-pad"><div class="filter-row"><div class="search-wrap"><span class="search-icon">⌕</span><input class="search-box" id="tableSearch" placeholder="Search title or YouTube ID…"></div><label class="field">Category<select id="catFilter"><option value="">All categories</option>${CATS.map(c=>`<option>${esc(c)}</option>`).join("")}</select></label><label class="field">Replay<select id="replayFilter"><option value="">Any status</option><option value="yes">Available</option><option value="no">Unavailable</option></select></label><label class="field">Min comments<input id="minComments" type="number" min="0" placeholder="0"></label><label class="field">Min timestamped<input id="minTS" type="number" min="0" placeholder="0"></label></div><div id="datasetTable"></div></div>`;}
function datasetTable(rows){const cols=[["Video",""],["Title","title"],["YouTube ID","videoId"],["Category","category"],["Duration","durationSeconds"],["Views","viewCount"],["Likes","likeCount"],["Comments","videoCommentCount"],["Timestamped","sourceTimestampedCommentCount"],["Replay",""],["Status",""],["Collected","collectionDate"]];return `<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map(([x,k])=>`<th ${k?`data-sort="${k}"`:""}>${x}${k&&app.sortKey===k?app.sortDir===1?" ↑":" ↓":""}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr><td><button class="link-button" data-video="${r.videoId}"><img class="thumb" src="https://i.ytimg.com/vi/${r.videoId}/default.jpg" alt="thumbnail"></button></td><td><button class="link-button video-title" data-video="${r.videoId}" title="${esc(r.title)}">${esc(r.title)}</button></td><td>${r.videoId}</td><td><span class="category-chip">${esc(CAT_SHORT[r.category]||r.category)}</span></td><td>${duration(r.durationSeconds)}</td><td>${fmt(r.viewCount)}</td><td>${fmt(r.likeCount)}</td><td>${fmt(r.videoCommentCount)}</td><td>${fmt(r.sourceTimestampedCommentCount)}</td><td>${r.bins.some(b=>b.replayIntensity!==null)?`<span class="pill green">Available</span>`:`<span class="pill amber">Unavailable</span>`}</td><td><span class="status-chip">PROCESSED</span></td><td>${date(r.collectionDate)}</td></tr>`).join("")}</tbody></table></div><div class="table-footer"><span>Showing ${rows.length} of ${app.videos.length} videos</span><span>Click column headings to sort</span></div>`;}
function videosPage(){return `${titleBlock("VIDEO LIBRARY","Videos","Select a video to open its player, 100-moment graph, and signal details together.",btn("Export list","export-dataset","soft"))}<div class="grid cols-3">${recs().map(r=>`<button class="card video-card" data-video="${r.videoId}"><img src="https://i.ytimg.com/vi/${r.videoId}/mqdefault.jpg" alt=""><span class="video-card-body"><span class="category-chip">${esc(CAT_SHORT[r.category]||r.category)}</span><b>${esc(r.title)}</b><small>${duration(r.durationSeconds)} · ${fmt(r.viewCount)} views · ${fmt(r.sourceTimestampedCommentCount)} timestamped</small></span></button>`).join("")}</div>`;}
function loadVideo(id){if(!app.records.has(id))return;app.videoId=id;app.bin=0;app.page="video";if(location.hash!=="#video")location.hash="video";$("#crumb").textContent="Video Detail";renderNav();renderPage();window.scrollTo(0,0);}
function videoPage(){const r=app.records.get(app.videoId)||recs()[0];if(!r)return overviewPage();const b=r.bins[app.bin]||r.bins[0];return `${titleBlock("VIDEO DETAIL",esc(r.title),`${esc(r.videoId)} · ${esc(CAT_SHORT[r.category]||r.category)} · ${duration(r.durationSeconds)}`,`${btn("← Dataset","dataset")}${btn("Open on YouTube ↗","youtube","soft")}`)}
 <div class="card video-hero"><div class="detail-player"><iframe src="https://www.youtube-nocookie.com/embed/${r.videoId}?start=${Math.floor(b.midpointSeconds)}&rel=0&playsinline=1" title="${esc(r.title)}" allow="accelerometer; autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe></div><div><div class="eyebrow">${esc(CAT_SHORT[r.category]||r.category)} · ${duration(r.durationSeconds)}</div><h2>${esc(r.title)}</h2><div class="video-facts">${fact("Views",fmt(r.viewCount))}${fact("Likes",fmt(r.likeCount))}${fact("Comments",fmt(r.videoCommentCount))}${fact("Timestamped",fmt(r.sourceTimestampedCommentCount))}${fact("Status","Processed")}</div></div></div>
 <div class="grid cols-2"><section class="card card-pad">${cardTitle("100-moment timeline","Toggle signals · hover for detail · select a moment to inspect")}${exportRow("timelineSvg")}${signalToggleMarkup()}<div class="salience-legend"><span><i class="high"></i>High</span><span><i class="medium"></i>Medium</span><span><i class="low"></i>Low salience</span></div><div id="detailTimeline">${timelineSvg(r,true)}</div><div class="timeline-axis"><span>0%</span><span>VIDEO PROGRESS</span><span>100%</span></div><div class="header-actions" style="margin-top:12px">${btn("Open Segment Explorer","segments","primary")}${btn("View comments","comments")}</div></section><section class="card card-pad">${cardTitle(`Moment ${String(app.bin+1).padStart(2,"0")} inspection`,`${duration(b.relativeStart*r.durationSeconds)} → ${duration(b.relativeEnd*r.durationSeconds)}`)}<div class="segment-stats">${stat("Replay intensity",fmt(b.replayIntensity,3))}${stat("Replay prominence",fmt(b.localReplayProminence,3))}${stat("Timestamp refs",fmt(b.timestampReferenceCount))}${stat("Comment score",fmt(b.logNormalizedTimestampCount,3))}${stat("Salience",fmt(salienceFor(r,app.bin).score,3))}</div><div class="salience-note ${salienceFor(r,app.bin).level}"><b>${salienceFor(r,app.bin).label} salience</b><span>Behavioral indicator; not a QoE rating.</span></div><div id="momentComments">${commentsFor(r,app.bin)}</div></section></div>`;}
function fact(a,b){return `<span class="video-fact"><b>${b}</b><small>${a}</small></span>`;}function stat(a,b){return `<div class="segment-stat"><small>${a}</small><b>${b}</b></div>`;}
function signalToggleMarkup(){return `<div class="signal-toggles" id="signalToggles">${[["R","Most Replayed intensity"],["P","Replay prominence"],["C","Timestamp-comment activity"],["E","Comment function / emotion"],["B","Behavioral salience"]].map(([k,l],i)=>`<label class="toggle"><input type="checkbox" data-signal="${k}" ${i===0||i===4?"checked":""}><span>${l}</span></label>`).join("")}</div>`;}
function feature(r,i){return app.featureMap.get(`${r.videoId}:${i}`)||{};}
function salienceRaw(r,i,weights=app.weights){const f=feature(r,i);const vector=[f.replayZ||0,f.prominenceZ||0,f.commentActivityZ||0,((f.emotionZ||0)+(f.qualityComplaintZ||0)+(f.confusionZ||0))/3];return vector.reduce((s,x,j)=>s+x*weights[j],0);}
function salienceFor(r,i){const key=`${r.videoId}:${app.weights.join("|")}`;if(!salienceCache.has(key)){const rows=r.bins.map((_,j)=>salienceRaw(r,j)),sorted=[...rows].sort((a,b)=>a-b);salienceCache.set(key,{rows,sorted});}const {rows,sorted}=salienceCache.get(key),score=rows[i]||0,rank=sorted.findIndex(x=>x>=score),q=rank/Math.max(1,sorted.length-1),level=q>=.8?"high":q<=.2?"low":"medium";return {score,level,label:level[0].toUpperCase()+level.slice(1)};}
function timelineSvg(r,interactive=false){const bins=r.bins,W=1000,H=260,L=38,R=10,T=12,B=25,cw=W-L-R,ch=H-T-B;const signals=interactive?new Set($$("[data-signal]").filter(x=>x.checked).map(x=>x.dataset.signal)):new Set(["R","P","C","B"]);const x=i=>L+(i+.5)*cw/100,y=v=>T+(1-v)*ch;const path=(a,fn)=>a.map((v,i)=>`${i?"L":"M"}${x(i).toFixed(1)},${fn(v).toFixed(1)}`).join(" ");let g="";for(let j=0;j<5;j++){const yy=T+ch*j/4;g+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#edf0f4"/><text x="${L-6}" y="${yy+3}" font-size="8" text-anchor="end" fill="#8b98a8">${(1-j/4).toFixed(1)}</text>`;}bins.forEach((b,i)=>{const lv=salienceFor(r,i).level,col=lv==="high"?"#46a878":lv==="medium"?"#e0ae4f":"#aeb8c5";g+=`<rect x="${L+i*cw/100}" y="${T+ch-5}" width="${cw/100+0.2}" height="5" fill="${col}" opacity=".75"/>`;});
 const vals={R:bins.map(b=>b.replayIntensity??0),P:bins.map((_,i)=>feature(r,i).prominenceZ||0),C:bins.map((_,i)=>feature(r,i).commentActivityZ||0),E:bins.map((_,i)=>((feature(r,i).emotionZ||0)+(feature(r,i).qualityComplaintZ||0))/2),B:bins.map((_,i)=>salienceRaw(r,i))};
 const colors={R:"#3977d5",P:"#edaa45",C:"#54a59d",E:"#929bd5",B:"#172d4d"};
 for(const k of signals){let arr=vals[k],min=Math.min(0,...arr),max=Math.max(.001,...arr);if(k==="R"){min=0;max=1}const norm=arr.map(v=>(v-min)/(max-min));if(k==="C")bins.forEach((b,i)=>{const bh=(b.timestampReferenceCount/Math.max(1,...bins.map(z=>z.timestampReferenceCount)))*ch*.35;g+=`<rect x="${(x(i)-2.2).toFixed(1)}" y="${(T+ch-bh).toFixed(1)}" width="4.4" height="${bh.toFixed(1)}" rx="1" fill="${colors[k]}" opacity=".45"/>`});else g+=`<path d="${path(norm,y)}" fill="none" stroke="${colors[k]}" stroke-width="${k==="B"?2.5:1.7}" stroke-linecap="round" stroke-linejoin="round" opacity="${k==="B"?.95:.85}"/>`;}
 bins.forEach((b,i)=>{const s=salienceFor(r,i);g+=`<rect class="chart-hit" data-bin="${i}" x="${L+i*cw/100}" y="${T}" width="${cw/100+0.2}" height="${ch}" fill="transparent" tabindex="0" aria-label="Moment ${i+1}, ${s.label} salience"/>`});g+=`<line x1="${x(app.bin)}" x2="${x(app.bin)}" y1="${T}" y2="${T+ch}" stroke="#c44949" stroke-dasharray="3 4"/>`;return `<svg class="chart-svg" id="timelineSvg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Behavior signals across video timeline">${g}</svg>`;}
function commentsFor(r,i){const list=r.comments.filter(c=>c.timestamps.some(t=>Math.floor(t.relativePosition*100)===i));if(!list.length)return `<div class="empty-state">No timestamped comments assigned to this moment.</div>`;return `<div class="comment-stack">${list.slice(0,4).map(c=>`<div class="comment-row"><span class="pill blue">${esc(LABEL[c.functionLabel]||c.functionLabel)}</span><p>${esc(c.cleanedText)}</p></div>`).join("")}</div>`;}

function behaviorPage(){const all=allSaliences(),dist=histBins(all.map(x=>x.score));return `${titleBlock("CURRENT RESEARCH AREA","Behavioral Analysis","Explore how replay activity, comment attention, and comment function combine into a segment-level salience indicator.")}
 <div class="card card-pad formula-card"><div><div class="eyebrow">BEHAVIORAL SALIENCE</div><div class="formula">B<sub>i</sub> = αR<sub>i</sub> + βP<sub>i</sub> + γC<sub>i</sub> + δE<sub>i</sub></div><small>Signals are standardized within each video before combining.</small></div><div class="weight-mode"><button class="btn ${app.customWeights?"":"soft"}" data-action="equal-weights">Equal weights</button><button class="btn ${app.customWeights?"soft":""}" data-action="custom-weights">Custom weights</button></div></div>
 <div class="grid cols-2" style="margin-top:14px"><section class="card card-pad">${cardTitle("Signal weights","Adjust how each behavioral signal contributes")}${["Replay intensity","Replay prominence","Timestamp-comment activity","Comment function / emotion"].map((l,i)=>`<label class="weight-slider"><span>${l}</span><input type="range" min="0" max="100" value="${Math.round(app.weights[i]*100)}" data-weight="${i}" ${app.customWeights?"":"disabled"}><b>${Math.round(app.weights[i]*100)}%</b></label>`).join("")}<div class="weight-total">Weights total <b>${Math.round(app.weights.reduce((a,b)=>a+b,0)*100)}%</b></div></section><section class="card card-pad">${cardTitle("Salience distribution","2,400 video moments · current weights")}${exportRow("salienceHistogram")}<svg class="histogram-svg" id="salienceHistogram" viewBox="0 0 1000 160" role="img" aria-label="Histogram of behavioral salience scores">${dist.map((n,i)=>{const w=1000/dist.length-6,h=Math.max(3,n/Math.max(...dist)*112);return `<rect x="${i*1000/dist.length+3}" y="${132-h}" width="${w}" height="${h}" rx="3" fill="#77a4dc"/>`}).join("")}<line x1="0" y1="133" x2="1000" y2="133" stroke="#e7ebf1"/></svg><div class="timeline-axis"><span>LOWER SALIENCE</span><span>HIGHER SALIENCE</span></div></section></div>
 <div class="grid cols-2" style="margin-top:14px"><section class="card card-pad">${cardTitle("Salience by category","Distribution of standardized behavioral scores")}${categoryDistribution()}</section><section class="card card-pad">${cardTitle("Signal correlation","Pearson correlation across 2,400 moments")}${correlationMatrix()}</section></div>
 <div class="grid cols-2" style="margin-top:14px"><section class="card card-pad">${cardTitle("Highest-salience moments","Top 10 across the current video sample")}<div id="highRank">${rankTable(all.sort((a,b)=>b.score-a.score).slice(0,10))}</div></section><section class="card card-pad">${cardTitle("Lowest-salience moments","Bottom 10 across the current video sample")}<div>${rankTable([...all].sort((a,b)=>a.score-b.score).slice(0,10))}</div></section></div><section class="card card-pad" style="margin-top:14px">${cardTitle("Signal contribution","Current weighting across replay, comments, and emotion/function signals")}${contributions()}</section>`;}
function allSaliences(){return recs().flatMap(r=>r.bins.map((_,i)=>({r,i,score:salienceRaw(r,i),b:r.bins[i],s:salienceFor(r,i)})));}
function histBins(xs,n=16){if(!xs.length)return Array(n).fill(0);let lo=Math.min(...xs),hi=Math.max(...xs);if(hi===lo)hi=lo+1;let a=Array(n).fill(0);for(let v of xs)a[Math.min(n-1,Math.floor((v-lo)/(hi-lo)*n))]++;return a;}
function categoryDistribution(){return `<div class="category-bars">${CATS.map(c=>{const xs=allSaliences().filter(x=>x.r.category===c).map(x=>x.score),bins=histBins(xs,24);return `<div class="category-dist-row"><span>${CAT_SHORT[c]}</span><div class="category-strip">${bins.map(v=>`<i style="opacity:${.16+v/Math.max(1,...bins)*.75}" title="${v}"></i>`).join("")}</div><small>n=${xs.length}</small></div>`}).join("")}</div>`;}
function pearson(a,b){const am=avg(a),bm=avg(b),num=a.reduce((s,x,i)=>s+(x-am)*(b[i]-bm),0),da=Math.sqrt(a.reduce((s,x)=>s+(x-am)**2,0)),db=Math.sqrt(b.reduce((s,x)=>s+(x-bm)**2,0));return da&&db?num/(da*db):0;}
function correlationMatrix(){const keys=["R","P","C","E","B"],vals=allSaliences().map(x=>{const f=feature(x.r,x.i);return [f.replayZ||0,f.prominenceZ||0,f.commentActivityZ||0,((f.emotionZ||0)+(f.qualityComplaintZ||0)+(f.confusionZ||0))/3,x.score]});return `<table class="corr-table"><thead><tr><th></th>${keys.map(k=>`<th>${k}</th>`).join("")}</tr></thead><tbody>${keys.map((k,i)=>`<tr><th>${k}</th>${keys.map((_,j)=>{const c=pearson(vals.map(v=>v[i]),vals.map(v=>v[j])),a=Math.abs(c);return `<td style="background:${c>=0?`rgba(57,119,213,${.06+a*.35})`:`rgba(196,73,73,${.06+a*.28})`}" title="r=${c.toFixed(2)}">${c.toFixed(2)}</td>`}).join("")}</tr>`).join("")}</tbody></table><div class="legend" style="margin-top:10px"><span>Blue = positive correlation</span><span>Red = negative correlation</span></div>`;}
function rankTable(rows){return `<div class="table-wrap"><table class="rank-table"><thead><tr><th>#</th><th>Video</th><th>Category</th><th>Moment</th><th>Timestamp</th><th>Replay</th><th>Comment</th><th>Salience</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td class="rank">${i+1}</td><td><button class="link-button" data-video="${x.r.videoId}">${esc(x.r.videoId)}</button></td><td>${esc(CAT_SHORT[x.r.category])}</td><td>${x.i+1}</td><td>${duration(x.b.midpointSeconds)}</td><td>${fmt(x.b.replayIntensity,2)}</td><td>${fmt(x.b.logNormalizedTimestampCount,2)}</td><td class="score">${x.score.toFixed(2)}</td></tr>`).join("")}</tbody></table></div>`;}
function contributions(){return ["Replay intensity","Replay prominence","Comment activity","Comment function / emotion"].map((x,i)=>`<div class="contribution-row"><span>${x}</span><div class="contribution-track"><i class="contribution-fill" style="width:${app.weights[i]*100}%"></i></div><b>${Math.round(app.weights[i]*100)}%</b></div>`).join("");}

function segmentsPage(){return `${titleBlock("TEMPORAL ANALYSIS","Segment Explorer","Filter and compare individual video moments by behavioral signals.",btn("Export visible CSV","export-segments","soft"))}<div class="card card-pad"><div class="filter-row"><label class="field">Video<select id="segVideo"><option value="">All videos</option>${recs().map(r=>`<option value="${r.videoId}">${esc(r.title.slice(0,55))}</option>`).join("")}</select></label><label class="field">Category<select id="segCategory"><option value="">All categories</option>${CATS.map(c=>`<option>${esc(c)}</option>`).join("")}</select></label><label class="field">Salience<select id="segLevel"><option value="">All levels</option><option>high</option><option>medium</option><option>low</option></select></label><label class="field">Moment #<input id="segBin" type="number" min="1" max="100" placeholder="Any"></label><label class="field">Timestamp<input id="segTime" placeholder="2:31" aria-label="Timestamp"></label><label class="field">Min replay<input id="segReplay" type="number" min="0" max="1" step=".05" placeholder="0"></label><label class="field">Min comments<input id="segComments" type="number" min="0" placeholder="0"></label></div><div id="segmentResults" class="grid cols-2"></div></div>`;}
function segmentCard(r,i){const b=r.bins[i],s=salienceFor(r,i),flag=app.flags[`${r.videoId}:${i}`]||"Candidate";return `<article class="card segment-card"><div class="segment-card-head"><span class="category-chip">${esc(CAT_SHORT[r.category])}</span><span class="pill ${s.level==="high"?"green":s.level==="medium"?"amber":""}">${s.label} salience</span></div><h3>${esc(r.title)}</h3><div class="segment-card-meta">Moment ${i+1} · ${duration(b.relativeStart*r.durationSeconds)} → ${duration(b.relativeEnd*r.durationSeconds)} · ${(b.relativeStart*100).toFixed(0)}–${(b.relativeEnd*100).toFixed(0)}%</div><div class="segment-card-metrics">${[["Replay",fmt(b.replayIntensity,2)],["Prominence",fmt(b.localReplayProminence,2)],["Timestamp refs",b.timestampReferenceCount],["Comment score",fmt(b.logNormalizedTimestampCount,2)],["Salience",s.score.toFixed(2)]].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join("")}</div><div class="segment-card-actions"><button class="btn soft" data-play="${r.videoId}:${i}">View segment</button><button class="btn" data-comments="${r.videoId}:${i}">View comments</button><select class="flag-select" data-flag="${r.videoId}:${i}">${["Candidate","Selected","Excluded","Needs Review"].map(x=>`<option ${x===flag?"selected":""}>${x}</option>`).join("")}</select></div></article>`;}
function candidatePage(){const all=allSaliences(),selected=app.selected.size;return `${titleBlock("BEHAVIORAL ANALYSIS","Candidate Moments","Shortlist moments for review based on behavioral salience. This does not start an experiment.",btn("Save shortlist","finalize-set","primary"))}<div class="grid cols-3" style="margin-bottom:14px">${metric("Selected moments",selected,"saved in this browser","✓")}${metric("Video categories",new Set([...app.selected].map(k=>app.records.get(k.split(":")[0])?.category).filter(Boolean)).size,"represented in selection","◫")}${metric("Candidate pool",all.length,"moments across the dataset","▥")}</div><div class="card card-pad" style="margin-bottom:14px">${cardTitle("Category balance","Check representation across video categories")}<div class="category-balance">${CATS.map(c=>{const n=[...app.selected].filter(k=>app.records.get(k.split(":")[0])?.category===c).length;return `<div><span>${CAT_SHORT[c]}</span><b>${n}</b><i><em style="width:${Math.min(100,n/Math.max(1,selected)*100)}%"></em></i></div>`}).join("")}</div></div><div class="candidate-columns">${[["high","High salience","Upper fifth of behavioral scores"],["medium","Medium salience","Middle range of behavioral scores"],["low","Low salience","Lower fifth of behavioral scores"]].map(([level,name,sub])=>{let rows=[...all].filter(x=>x.s.level===level).sort((a,b)=>b.score-a.score).slice(0,12);return `<section class="card candidate-column"><h3>${name}</h3><p>${sub}</p>${rows.map(x=>candidateCheckbox(x)).join("")}</section>`}).join("")}</div>`;}
function clipWindow(r,i){const target=Number(app.status?.stimulusClipDurationSeconds)||30,mid=r.bins[i].midpointSeconds;let start=Math.max(0,mid-target/2),end=Math.min(r.durationSeconds,start+target);if(end-start<target)start=Math.max(0,end-target);return {start,end,length:end-start};}
function candidateCheckbox(x){const k=`${x.r.videoId}:${x.i}`,w=clipWindow(x.r,x.i);return `<label class="candidate-item"><input type="checkbox" data-candidate="${k}" ${app.selected.has(k)?"checked":""}><span><b>${esc(x.r.title.slice(0,55))}</b><small>${CAT_SHORT[x.r.category]} · moment ${x.i+1} · clip ${duration(w.start)}–${duration(w.end)} (${Math.round(w.length)}s) · B ${x.score.toFixed(2)}</small></span></label>`;}

function experimentsPage(){const rows=app.status?.measurementTemplate?[]:[];return `${titleBlock("CONTROLLED MEASUREMENTS","QoE Experiments","Record network-side and objective quality outcomes separately from viewer-behavior signals.",btn("Download measurement template","download-template","soft"))}<div class="placeholder-callout"><b>Measurement status: awaiting controlled test results</b>Behavioral salience is a viewer-activity signal. Computational QoE is a separate technical measurement; neither is presented as the other.</div><div class="grid cols-4" style="margin-bottom:14px">${metric("Candidate moments",app.candidates.length,"from current segment shortlist","▥")}${metric("Planned conditions",app.status?.plannedMeasurementRows||0,"three impairment types","◉")}${metric("Measured conditions",app.model?.trainingRows||0,"objective outcomes entered","✓")}${metric("Objective quality",app.model?"Available":"Pending","VMAF / SSIM / PSNR","▧")}</div><section class="card card-pad">${cardTitle("Experiment condition fields","Planned measurement schema")}${experimentTable()}</section><div class="grid cols-2" style="margin-top:14px"><section class="card card-pad">${cardTitle("Behavioral salience Bᵢ","Public replay and comment behavior")}${metricInline("Signal type","Behavioral data","Blue")}${metricInline("What it describes","Viewer attention and comment activity","Observed public signals")}</section><section class="card card-pad">${cardTitle("Computational QoE Qᵢ(comp)","Objective streaming and quality metrics")}${metricInline("Signal type","Technical measurement","Independent outcome")}${metricInline("What it describes","Impairment severity and objective quality","Requires controlled runs")}</section></div>`;}
function experimentTable(){return `<div class="table-wrap"><table class="data-table"><thead><tr>${["Video","Moment","Condition","Severity","VMAF Δ","SSIM Δ","PSNR Δ","Rebuffer (s)","Notes"].map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${(app.candidates.slice(0,10).flatMap(c=>["Rebuffering","Bitrate reduction","Resolution reduction"]).map((x,i)=>`<tr><td>${c.videoId}</td><td>${c.binIndex+1}</td><td>${x}</td><td>Planned</td><td>—</td><td>—</td><td>—</td><td>—</td><td>Not measured</td></tr>`)).join("")}</tbody></table></div><p class="table-footer">Showing a preview of planned conditions. Objective outcomes are not fabricated.</p>`;}
function metricInline(a,b,c){return `<div class="summary-line"><span class="pending-icon">◉</span><span><b>${a}</b><small>${b}</small></span><i class="pill">${c}</i></div>`;}

function humanPage(){return `${titleBlock("STUDY DESIGN PREVIEW","Human Study","Preview the blinded rating experience and review the planned study setup.")}<div class="placeholder-callout"><b>Preview only · clips are not prepared and responses are not saved</b>This is a visual prototype. The short video stimuli and secure response collection are not connected yet.</div><div class="header-actions" style="margin-bottom:12px"><button class="btn ${!app.participant?"soft":""}" data-action="researcher-mode">Researcher view</button><button class="btn ${app.participant?"soft":""}" data-action="participant-mode">Participant preview</button></div>${app.participant?participantPreview():researcherPreview()}`;}
function researcherPreview(){return `<div class="grid cols-2"><section class="card card-pad">${cardTitle("Study setup","Researcher mode")}${["Select candidate clips","Assign clean and impaired versions","Randomize sample order","Configure rating questions","Create a study session"].map((x,i)=>`<div class="summary-line"><span class="pending-icon">${i+1}</span><span><b>${x}</b><small>Available after experiment clips and secure study storage are configured.</small></span><i class="pill amber">PLANNED</i></div>`).join("")}</section><section class="card card-pad">${cardTitle("Response export","No response data yet")}<div class="empty-state"><div class="empty-icon">♙</div>Participant results will appear here after an approved study is deployed.</div></section></div>`;}
function participantPreview(){let r=app.records.get(app.videoId)||recs()[0],candidate=app.candidates[app.studyIndex%Math.max(1,app.candidates.length)],video=candidate?app.records.get(candidate.videoId):r,win=candidate?{start:candidate.clipStartSeconds,end:candidate.clipEndSeconds,length:candidate.clipDurationSeconds}:clipWindow(r,app.bin);return `<section class="card card-pad participant"><div class="eyebrow">PARTICIPANT EXPERIENCE PREVIEW · SAMPLE ${app.studyIndex+1} OF 20</div><h2>How did that moment feel?</h2><div class="study-clip"><img src="https://i.ytimg.com/vi/${video.videoId}/hqdefault.jpg" alt="Video thumbnail"><div><b>Short clip stimulus</b><span>${duration(win.length)} · ${duration(win.start)}–${duration(win.end)}</span><small>Clean and impaired versions will use the same ${Math.round(win.length)}-second clip.</small></div><i>CLIP NOT PREPARED</i></div>${["How annoying was the interruption?","How severe was the interruption?","How would you rate the overall video quality?"].map(q=>`<fieldset><legend>${q}</legend><div class="rating-row">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="${q.slice(0,8)}"><span>${n}</span></label>`).join("")}</div></fieldset>`).join("")}<fieldset><legend>Would you continue watching this video?</legend><div class="rating-row">${["Yes","Maybe","No"].map(n=>`<label><input type="radio" name="continue"><span>${n}</span></label>`).join("")}</div></fieldset><button class="btn primary" data-action="next-sample">Next sample →</button><small class="preview-disclaimer">Preview responses are not saved. Participants see only the short clip and rating questions, never salience or impairment labels.</small></section>`;}

function modelsPage(){return `${titleBlock("FUTURE MODEL EVALUATION","Model Comparison","Compare traditional computational baselines with behavior-aware models.")}<div class="placeholder-callout"><b>Held-out human evaluation stays locked</b>Human evaluation data should not be used to train or tune either model.</div><div class="grid cols-2">${modelCard("Traditional Model","Computational QoE + video controls","Waiting for measured objective labels")}${modelCard("Behavior-Aware Model","Computational QoE + behavioral salience + controls","Waiting for measurements and subjective calibration")}</div><div class="grid cols-2" style="margin-top:14px"><section class="card card-pad">${cardTitle("Prediction vs observed","Validation results will appear here")}<div class="empty-state"><div class="empty-icon">⌁</div>No validated predictions yet.</div></section><section class="card card-pad">${cardTitle("Feature ablation","Contribution by input signal")}<div class="empty-state">Model comparison requires measured outcomes and a held-out evaluation set.</div></section></div>`;}
function modelCard(n,f,s){return `<section class="card card-pad model-card"><span class="pill amber">NOT TRAINED</span><h2>${n}</h2><p>${f}</p><div class="model-dataset"><span>Training set <b>—</b></span><span>Validation set <b>—</b></span><span>Test set <b>🔒 Held out</b></span></div><div class="metric-row">${["Correlation","MAE","RMSE","R²"].map(x=>`<span>${x}<b>—</b></span>`).join("")}</div><small>${s}</small></section>`;}
function resultsPage(){return `${titleBlock("PUBLICATION DASHBOARD","Results","Separate behavioral observations, computational measurements, and subjective viewer ratings.",btn("Export results","export-results","soft"))}<div class="grid cols-3">${["Behavioral dataset","Traditional QoE baseline","Subjective QoE","Traditional vs behavior-aware","Ablation analysis","Category analysis","Impairment analysis"].map((x,i)=>`<section class="card placeholder-card"><span class="pill ${i===0?"green":"amber"}">${i===0?"DATA READY":"AWAITING DATA"}</span><h3 style="margin-top:10px">${x}</h3><p>${i===0?"Video behavior signals and salience features are available.":"This publication view will populate after controlled experiments and held-out evaluation."}</p></section>`).join("")}</div>`;}

function collectionPage(){return `${titleBlock("DATA PIPELINE","Data Collection","Add and process public YouTube video signals for the research dataset.")}<div class="placeholder-callout"><b>Collection service is not connected to this dashboard</b>The API key stays on the research machine. This browser form is a UI preview and will not start a collection job.</div><div class="grid cols-2"><section class="card card-pad">${cardTitle("Add a YouTube video","Use a YouTube video URL or video ID")}<label class="field">YouTube URL or ID<input id="newVideo" placeholder="https://youtube.com/watch?v=…"></label><label class="field" style="margin-top:11px">Category<select id="newCategory">${CATS.map(c=>`<option>${esc(c)}</option>`).join("")}</select></label><button class="btn primary" data-action="collect-preview" style="margin-top:12px">Collect data</button></section><section class="card card-pad">${cardTitle("Collection stages","Typical data processing flow")}${["Validate video","Retrieve metadata","Retrieve Most Replayed markers","Retrieve comments","Detect timestamps","Generate temporal bins","Preprocess signals","Calculate behavioral features"].map((x,i)=>`<div class="summary-line"><span class="check-icon ${i>4?"amber-icon":""}">${i<6?"✓":"○"}</span><span><b>${i+1}. ${x}</b><small>${i<6?"Completed for current dataset":"Next analysis step"}</small></span></div>`).join("")}</section></div><section class="card card-pad" style="margin-top:14px">${cardTitle("Batch collection","Paste video IDs or import a CSV") }<textarea id="batchIds" rows="4" placeholder="One YouTube video ID per line"></textarea><div class="header-actions" style="margin-top:9px"><button class="btn" data-action="import-batch">Validate IDs</button><span class="pill amber">Collection backend not configured</span></div></section>`;}

function progressPage(){const states=phaseStatus();return `${titleBlock("RESEARCH ROADMAP","Project Progress","Research stages, outputs, and verification checkpoints.")}<div class="card card-pad" style="margin-bottom:14px">${cardTitle("Overall completion","Three stages complete · behavioral analysis underway")}<div class="overall-progress"><span>33%</span><i><b style="width:40%"></b></i><small>3 completed · 1 in progress · 5 upcoming</small></div></div><div class="phase-grid">${STAGES.map((name,i)=>{let s=states[i],titles=["24-video balanced dataset","Public metadata, replay, and comments","100-bin aligned signal dataset","Standardized behavioral features and shortlist","Controlled impairment measurements","Blinded participant responses","Calibration and data augmentation","Held-out model evaluation","Adaptive streaming prototype"];let criteria=["Four videos per category selected.","Public signals collected and organized.","Validity checks pass; comment labels await manual agreement review.","Feature vectors and candidate moments prepared; test measurements still needed.","Generate objective quality outcomes for the planned conditions.","Collect consented human ratings with blinded conditions.","Calibrate predictions using human study outcomes.","Compare models on held-out human evaluation data.","Build only if findings and project scope support it."];return `<article class="card phase-card"><div class="phase-card-top"><h3>Stage ${i+1} · ${name}</h3><span class="pill ${s==="complete"?"green":s==="current"?"blue":s==="conditional"?"amber":""}">${s==="complete"?"Complete":s==="current"?"In progress":s==="conditional"?"Conditional":"Not started"}</span></div><div class="progress-bar"><i class="${s==="current"?"current":""}" style="width:${s==="complete"?100:s==="current"?45:0}%"></i></div><p><b>Deliverable:</b> ${titles[i]}<br><b>Check:</b> ${criteria[i]}</p></article>`}).join("")}</div>`;}
function settingsPage(){return `${titleBlock("WORKSPACE","Settings","Display and research-analysis preferences.")}<section class="card card-pad">${cardTitle("Behavioral salience weights","Equal weights are the default for exploratory analysis")}${["Replay intensity","Replay prominence","Timestamp comments","Comment function / emotion"].map((n,i)=>`<label class="weight-slider"><span>${n}</span><input type="range" min="0" max="100" value="${Math.round(app.weights[i]*100)}" data-weight="${i}"><b>${Math.round(app.weights[i]*100)}%</b></label>`).join("")}<div class="header-actions" style="margin-top:12px">${btn("Reset equal weights","equal-weights","soft")}</div></section><section class="card card-pad" style="margin-top:14px">${cardTitle("Data and privacy") }<p class="small-note">This static dashboard reads locally generated JSON files. Do not publish raw comment exports, commenter identifiers, API keys, or human-study responses.</p></section>`;}

function bindPage(){
  $$("[data-action]").forEach(b=>b.onclick=()=>action(b.dataset.action,b));
  $$("[data-export]").forEach(b=>b.onclick=()=>exportVisualization(b.dataset.export));
  $$("[data-video]").forEach(b=>b.onclick=()=>loadVideo(b.dataset.video));
  $$("[data-play]").forEach(b=>b.onclick=()=>{const [id,n]=b.dataset.play.split(":");app.videoId=id;app.bin=Number(n);navigate("video")});
  $$("[data-comments]").forEach(b=>b.onclick=()=>{const [id,n]=b.dataset.comments.split(":");app.videoId=id;app.bin=Number(n);navigate("video")});
  $$("[data-weight]").forEach(x=>{x.oninput=()=>{app.weights[Number(x.dataset.weight)]=Number(x.value)/100;saveWeights();salienceCache.clear();const value=x.parentElement.querySelector("b");if(value)value.textContent=`${x.value}%`;};x.onchange=()=>navigate(app.page,false);});
  if(app.page==="dataset")bindDatasetFilters();if(app.page==="segments")bindSegmentFilters();
  $$("[data-candidate]").forEach(x=>x.onchange=()=>{const k=x.dataset.candidate;x.checked?app.selected.add(k):app.selected.delete(k);saveSelection();navigate("candidates",false)});
  $$("[data-flag]").forEach(x=>x.onchange=()=>{app.flags[x.dataset.flag]=x.value;localStorage.setItem("qoe-flags",JSON.stringify(app.flags));toast(`Moment marked ${x.value.toLowerCase()}`)});
  $$("[data-signal]").forEach(x=>x.onchange=()=>{const host=$("#detailTimeline");if(host){host.innerHTML=timelineSvg(app.records.get(app.videoId),true);bindTimeline();}});
  bindTimeline();
}
function bindTimeline(){const svg=$("#timelineSvg");if(!svg)return;$$(".chart-hit",svg).forEach(hit=>{const show=(e)=>{const r=app.records.get(app.videoId),i=Number(hit.dataset.bin),b=r.bins[i],s=salienceFor(r,i);app.bin=i;const tip=$("#tooltip")||Object.assign(document.body.appendChild(document.createElement("div")),{id:"tooltip",className:"chart-tooltip"});tip.innerHTML=`<b>Moment ${i+1}</b> · ${duration(b.relativeStart*r.durationSeconds)}–${duration(b.relativeEnd*r.durationSeconds)}<br>Position ${(b.relativeStart*100).toFixed(1)}–${(b.relativeEnd*100).toFixed(1)}% · Replay ${fmt(b.replayIntensity,3)}<br>Prominence ${fmt(b.localReplayProminence,3)} · Timestamp refs ${b.timestampReferenceCount}<br>Comment score ${fmt(b.logNormalizedTimestampCount,3)} · Salience ${s.label} (${s.score.toFixed(2)})`;tip.style.left=`${Math.min(window.innerWidth-245,e.clientX+12)}px`;tip.style.top=`${Math.max(5,e.clientY-45)}px`;};hit.onmousemove=show;hit.onmouseleave=()=>$("#tooltip")?.remove();hit.onclick=()=>{const r=app.records.get(app.videoId);app.bin=Number(hit.dataset.bin);navigate("video",false);};hit.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();hit.click();}};});}
function bindDatasetFilters(){const update=()=>{const q=$("#tableSearch").value.toLowerCase(),cat=$("#catFilter").value,replay=$("#replayFilter").value,minC=Number($("#minComments").value||0),minT=Number($("#minTS").value||0);let rows=recs().filter(r=>(!q||`${r.title} ${r.videoId}`.toLowerCase().includes(q))&&(!cat||r.category===cat)&&(!replay||(r.bins.some(b=>b.replayIntensity!==null))===(replay==="yes"))&&(r.videoCommentCount||0)>=minC&&(r.sourceTimestampedCommentCount||0)>=minT);if(app.sortKey)rows.sort((a,b)=>{let x=a[app.sortKey],y=b[app.sortKey];if(typeof x==="string")return x.localeCompare(y)*app.sortDir;return ((Number(x)||0)-(Number(y)||0))*app.sortDir;});$("#datasetTable").innerHTML=datasetTable(rows);$$('[data-video]',$("#datasetTable")).forEach(b=>b.onclick=()=>loadVideo(b.dataset.video));$$('th[data-sort]',$("#datasetTable")).forEach(h=>h.onclick=()=>{if(app.sortKey===h.dataset.sort)app.sortDir*=-1;else{app.sortKey=h.dataset.sort;app.sortDir=1;}update();});};["tableSearch","catFilter","replayFilter","minComments","minTS"].forEach(id=>$("#"+id).addEventListener("input",update));update();}
function parseTime(s){const p=String(s||"").trim().split(":").map(Number);if(p.length===2&&p.every(Number.isFinite))return p[0]*60+p[1];if(p.length===3&&p.every(Number.isFinite))return p[0]*3600+p[1]*60+p[2];return null;}
function bindSegmentFilters(){const update=()=>{const id=$("#segVideo").value,cat=$("#segCategory").value,level=$("#segLevel").value,n=Number($("#segBin").value)-1,time=parseTime($("#segTime").value),minR=Number($("#segReplay").value||0),minC=Number($("#segComments").value||0);let html=[];for(const r of recs()){if(id&&r.videoId!==id||cat&&r.category!==cat)continue;for(let i=0;i<r.bins.length;i++){if(Number.isFinite(n)&&n>=0&&i!==n)continue;const b=r.bins[i],s=salienceFor(r,i);if(level&&s.level!==level||(b.replayIntensity||0)<minR||b.timestampReferenceCount<minC||time!==null&&(time<b.relativeStart*r.durationSeconds||time>=b.relativeEnd*r.durationSeconds))continue;html.push(segmentCard(r,i));if(html.length>=100)break;}if(html.length>=100)break;}$("#segmentResults").innerHTML=html.length?html.join(""):`<div class="empty-state">No moments match these filters.</div>`;bindPageActions();};["segVideo","segCategory","segLevel","segBin","segTime","segReplay","segComments"].forEach(id=>$("#"+id).addEventListener("input",update));update();}
function bindPageActions(){ $$("[data-video]").forEach(b=>b.onclick=()=>loadVideo(b.dataset.video));$$("[data-play]").forEach(b=>b.onclick=()=>{const [id,n]=b.dataset.play.split(":");app.videoId=id;app.bin=Number(n);navigate("video")});$$("[data-comments]").forEach(b=>b.onclick=()=>{const [id,n]=b.dataset.comments.split(":");app.videoId=id;app.bin=Number(n);navigate("video")});$$("[data-flag]").forEach(x=>x.onchange=()=>{app.flags[x.dataset.flag]=x.value;localStorage.setItem("qoe-flags",JSON.stringify(app.flags));toast("Selection status saved locally")});}

function action(name,el){switch(name){case"overview":navigate("overview");break;case"behavior":navigate("behavior");break;case"videos":navigate("videos");break;case"progress":navigate("progress");break;case"comments":setTimeout(()=>$("#momentComments")?.scrollIntoView({behavior:"smooth"}),80);break;case"youtube":window.open(`https://www.youtube.com/watch?v=${app.videoId}`,"_blank","noopener");break;case"export-dataset":downloadCsv("qoe-video-dataset.csv",["videoId","title","category","durationSeconds","viewCount","likeCount","videoCommentCount","collectedCommentCount","sourceTimestampedCommentCount"],recs().map(r=>[r.videoId,r.title,r.category,r.durationSeconds,r.viewCount,r.likeCount,r.videoCommentCount,r.collectedCommentCount,r.sourceTimestampedCommentCount]));break;case"export-segments":exportSegments();break;case"export-results":toast("Results export becomes available when study data exists.");break;case"refresh":location.reload();break;case"equal-weights":app.weights=[.25,.25,.25,.25];app.customWeights=false;saveWeights();salienceCache.clear();navigate(app.page,false);break;case"custom-weights":app.customWeights=true;navigate("behavior",false);break;case"finalize-set":app.selected.forEach(k=>app.flags[k]="Selected");localStorage.setItem("qoe-flags",JSON.stringify(app.flags));toast(`${app.selected.size} moments saved as the current experimental shortlist.`);break;case"download-template":downloadTemplate();break;case"participant-mode":app.participant=true;navigate("human",false);break;case"researcher-mode":app.participant=false;navigate("human",false);break;case"next-sample":app.studyIndex=(app.studyIndex+1)%20;navigate("human",false);break;case"add-video":toast("Video collection requires the local YouTube API collection process.");break;case"import-ids":toast("Batch collection is not connected to a collection service.");break;case"collect-preview":toast("No API request was sent. Collection service is not configured.");break;case"import-batch":toast("IDs can be validated after a collection service is connected.");break;default:if(NAV.some(x=>x[2]===name))navigate(name);}}

function downloadCsv(name,heads,rows){const body=[heads,...rows].map(r=>r.map(csvEscape).join(",")).join("\n");download(name,body,"text/csv");}
function exportVisualization(spec){const [id,type]=spec.split(":");if(type==="csv"){if(id==="timelineSvg"){const r=app.records.get(app.videoId);downloadCsv(`${r.videoId}-signals.csv`,["videoId","binIndex","startSeconds","endSeconds","relativeStart","relativeEnd","replayIntensity","replayProminence","timestampCommentCount","commentScore","salience","salienceLevel"],r.bins.map((b,i)=>[r.videoId,i,b.relativeStart*r.durationSeconds,b.relativeEnd*r.durationSeconds,b.relativeStart,b.relativeEnd,b.replayIntensity,b.localReplayProminence,b.timestampReferenceCount,b.logNormalizedTimestampCount,salienceFor(r,i).score,salienceFor(r,i).label]));}else exportSegments();return;}const source=$("#"+id);if(!source){toast("Chart is not available for export.");return;}const clone=source.cloneNode(true);clone.setAttribute("xmlns","http://www.w3.org/2000/svg");clone.setAttribute("width",source.viewBox.baseVal.width||1000);clone.setAttribute("height",source.viewBox.baseVal.height||250);clone.querySelectorAll(".chart-hit").forEach(x=>x.remove());const xml=new XMLSerializer().serializeToString(clone),blob=new Blob([xml],{type:"image/svg+xml;charset=utf-8"});if(type==="svg"){download(`${id}.svg`,xml,"image/svg+xml");return;}const url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{const c=document.createElement("canvas");c.width=img.width;c.height=img.height;c.getContext("2d").drawImage(img,0,0);c.toBlob(out=>{const a=document.createElement("a");a.href=URL.createObjectURL(out);a.download=`${id}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);URL.revokeObjectURL(url);},"image/png");};img.onerror=()=>{URL.revokeObjectURL(url);toast("This chart could not be exported as PNG.");};img.src=url;}
function exportSegments(){const rows=allSaliences();downloadCsv("qoe-segments.csv",["videoId","category","binIndex","startSeconds","endSeconds","replayIntensity","replayProminence","timestampReferences","commentScore","salience"],rows.map(x=>[x.r.videoId,x.r.category,x.i,x.b.relativeStart*x.r.durationSeconds,x.b.relativeEnd*x.r.durationSeconds,x.b.replayIntensity,x.b.localReplayProminence,x.b.timestampReferenceCount,x.b.logNormalizedTimestampCount,x.score]));}
function downloadTemplate(){const header=["videoId","binIndex","clipStartSeconds","clipEndSeconds","clipDurationSeconds","impairment","severity","severityValue","referenceClipPath","impairedClipPath","vmafDelta","ssimDelta","psnrDelta","rebufferDurationSeconds","computationalQoeScore"];const lines=[header.join(",")],chosen=app.selected.size?[...app.selected].map(k=>{const [videoId,n]=k.split(":"),r=app.records.get(videoId),i=Number(n),w=clipWindow(r,i);return {videoId,binIndex:i,clipStartSeconds:w.start,clipEndSeconds:w.end,clipDurationSeconds:w.length};}):app.candidates;for(const c of chosen)for(const [imp,levels] of [["rebuffering",[["2s",2],["5s",5]]],["bitrate_reduction",[["50_percent",.5],["25_percent",.75]]],["resolution_reduction",[["50_percent",.5],["25_percent",.75]]]])for(const [sev,val] of levels)lines.push([c.videoId,c.binIndex,c.clipStartSeconds,c.clipEndSeconds,c.clipDurationSeconds,imp,sev,val,`media/${c.videoId}/moment-${c.binIndex}-reference.mp4`,`media/${c.videoId}/moment-${c.binIndex}-${imp}-${sev}.mp4`,"","","","",""].map(csvEscape).join(","));download("controlled-qoe-measurements.csv",lines.join("\n"),"text/csv");}
function download(name,body,type="text/plain"){const a=document.createElement("a"),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
function csvEscape(v){return `"${String(v??"").replaceAll('"','""')}"`;}
function saveWeights(){localStorage.setItem("qoe-weights",JSON.stringify(app.weights));}function loadWeights(){const a=JSON.parse(localStorage.getItem("qoe-weights")||"null");return Array.isArray(a)&&a.length===4?a:[.25,.25,.25,.25];}function saveSelection(){localStorage.setItem("qoe-selected",JSON.stringify([...app.selected]));}
function fmt(v,d=0){if(v===null||v===undefined||!Number.isFinite(Number(v)))return"—";return Number(v).toLocaleString(undefined,{maximumFractionDigits:d});}function avg(a){return a.length?a.reduce((s,x)=>s+x,0)/a.length:0;}function duration(s){s=Math.max(0,Math.floor(Number(s)||0));let h=Math.floor(s/3600),m=Math.floor(s%3600/60),z=s%60;return h?`${h}:${String(m).padStart(2,"0")}:${String(z).padStart(2,"0")}`:`${m}:${String(z).padStart(2,"0")}`;}function date(s){return s?new Date(s).toLocaleDateString():"—";}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}let toastTimer;function toast(s){const t=$("#toast");t.textContent=s;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2400);}
init();
